sys_ws_operation.script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var body;
    try {
        body = request.body.data;
    } catch (e1) {
        try {
            body = JSON.parse(request.body.dataString);
        } catch (e2) {
            body = {};
        }
    }
    if (!body) { body = {}; }

    var sessionId = (body.session_id || '').toString().trim();

    if (!sessionId) {
        response.setStatus(400);
        response.setBody({ error: 'session_id is required.' });
        return;
    }

    var logger  = new x_146833_claudec_0.ClaudeRequestLogger();
    var records = logger.getSessionHistory(sessionId);

    // Load reconstructed message block conversation turns
    var mgr      = new x_146833_claudec_0.ClaudeConversationManager();
    var messages = mgr.load_messages(sessionId);

    // Compute session-level aggregates
    var totalIn  = 0;
    var totalOut = 0;
    var totalMs  = 0;
    for (var i = 0; i < records.length; i++) {
        totalIn  += records[i].input_tokens;
        totalOut += records[i].output_tokens;
        totalMs  += records[i].duration_ms;
    }

    response.setStatus(200);
    response.setBody({
        session_id:          sessionId,
        request_count:       records.length,
        total_input_tokens:  totalIn,
        total_output_tokens: totalOut,
        total_duration_ms:   totalMs,
        messages:            messages,
        requests:            records
    });

})(request, response);
